type State={profile:any;recipes:Recipe[];shelf:any[];sources:any[];versions:any[];transfers:any[];myEvents:any[];externalLinks:any[];rewards:any};
const blank={title:'',description:'',ingredients:'',steps:'',minutes:20,servings:2,category:'主菜',image:'none'};
const explorer=(s:string)=>'https://explorer.solana.com/tx/'+encodeURIComponent(s)+'?cluster=devnet';
function Food({image,className=''}:{image:string;className?:string}){if(image.startsWith('photo:'))return <Photo id={image.slice(6)} className={'food '+className}/>;if(image.startsWith('grid:')){const i=Number(image.slice(5));return <div role="img" aria-label="AI生成のサンプル料理写真" className={'food food-grid '+className} style={{backgroundPosition:`${i%3*50}% ${Math.floor(i/3)*100}%`}}/>;}return <div className={'food food-none '+className}><ChefHat size={48}/><span>あなたのひらめきの一皿</span></div>;}
function Avatar({name='?'}:{name?:string}){return <span className="avatar">{name.slice(0,1)}</span>;}
export default function Studio(){
const [data,setData]=useState<State|null>(null),[error,setError]=useState(''),[signIn,setSignIn]=useState(''),[view,setView]=useState('discover'),[category,setCategory]=useState('すべて'),[query,setQuery]=useState(''),[sort,setSort]=useState('new'),[selected,setSelected]=useState<Recipe|null>(null),[privateItem,setPrivateItem]=useState<any>(null),[editor,setEditor]=useState<any>(null),[importOpen,setImportOpen]=useState(false),[sourceOpen,setSourceOpen]=useState(false),[help,setHelp]=useState(false),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[aiStatus,setAiStatus]=useState(''),[checks,setChecks]=useState<number[]>([]),[consent,setConsent]=useState(false),[similar,setSimilar]=useState<any[]>([]),[authorFilter,setAuthorFilter]=useState(''),[report,setReport]=useState(false),[reportReason,setReportReason]=useState(''),[testTransfer,setTestTransfer]=useState(false),[recipient,setRecipient]=useState(''),[testSaves,setTestSaves]=useState(12),[testCooks,setTestCooks]=useState(8);
const [aiSuggestion,setAiSuggestion]=useState<RecipeSuggestion|null>(null),[undoDraft,setUndoDraft]=useState<RecipeDraft|null>(null);
const [aiTask,setAiTask]=useState<'compose'|'refine'|'import'>('compose'),[aiError,setAiError]=useState(''),[aiCleanupAvailable,setAiCleanupAvailable]=useState(false),[noticeTone,setNoticeTone]=useState<'success'|'error'>('success');
const [hasDraft,setHasDraft]=useState(false),[draftSaved,setDraftSaved]=useState(false),[shareFallback,setShareFallback]=useState(''),[mediaNames,setMediaNames]=useState<string[]>([]),[mediaBusy,setMediaBusy]=useState(false),[mediaKey,setMediaKey]=useState(0);
const [importMedia,setImportMedia]=useState<Array<{base64:string;mimeType:string}>>([]);
const [importForm,setImportForm]=useState({url:'',title:'',notes:'',ingredients:'',steps:''}),[sourceForm,setSourceForm]=useState({recipe:'',url:''}),[profileForm,setProfileForm]=useState({name:'',bio:''});
const [week,setWeek]=useState(weekStart()),[notificationOpen,setNotificationOpen]=useState(false),[cookRecipe,setCookRecipe]=useState<Recipe|null>(null),[arrangeRecipe,setArrangeRecipe]=useState<Recipe|null>(null),[thread,setThread]=useState<CookPost|null>(null);
const community=useCommunity(data?.profile.id,week);
const feed=useRecipeFeed(query,category,authorFilter,sort,data);
const [publicationConflict,setPublicationConflict]=useState<Recipe|null>(null);
const cloud=useCloudDraft(data?.profile.id,editor,setEditor,community.load);
const communityError=(message:string)=>flash(message,'error');
async function refreshAll(){await Promise.all([load(),community.load()]);}
async function openRecipeId(id:string){await act(async()=>{const r=await apiFetch('/api/app?action=recipe&id='+encodeURIComponent(id));const j=await r.json();if(!r.ok)throw Error(j.error||'原本を取得できませんでした。');setData(p=>p?{...p,recipes:[...p.recipes.filter(r=>r.id!==id),j.recipe]}:p);setThread(null);setNotificationOpen(false);openRecipe(j.recipe);});}
async function openNotice(n:Notice){if(n.post){const result=await communityApi({op:'post',post:n.post},data?.profile.id);setNotificationOpen(false);setThread(result.post);}else if(n.recipe){setNotificationOpen(false);openRecipeId(n.recipe);}}
const deepLinkHandled=useRef(false); const timer=useRef<any>(null),busyRef=useRef(false);
const flash=(s:string,tone:'success'|'error'='success')=>{setNotice(s);setNoticeTone(tone);clearTimeout(timer.current);timer.current=setTimeout(()=>setNotice(''),6500);};
async function api(b:any){const r=await apiFetch('/api/app',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)});const j:any=await r.json();if(!r.ok){if(r.status===401)setSignIn('expired');const e:any=Error(j.error||'操作に失敗しました。');e.similar=j.similar;e.publicationConflict=j.publicationConflict;e.current=j.current;throw e;}return j;}
async function load(){try{let r=await apiFetch('/api/app',{cache:'no-store'});let j:any=await r.json();if(r.status===401){setSignIn('expired');return;}if(!r.ok)throw Error(j.error);if(j.needsInit){await api({op:'init'});r=await apiFetch('/api/app',{cache:'no-store'});j=await r.json();if(!r.ok)throw Error(j.error);}setData(j);setProfileForm({name:j.profile.name,bio:j.profile.bio});setError('');return j as State;}catch(e){setError((e as Error).message);}}
async function act(fn:()=>Promise<any>){if(busyRef.current)return;busyRef.current=true;setBusy(true);setAiStatus('');try{await fn();}catch(e){flash((e as Error).message,'error');}finally{busyRef.current=false;setBusy(false);}}
useEffect(()=>{load();return()=>clearTimeout(timer.current);},[]);
useEffect(()=>{if(!data||deepLinkHandled.current)return;deepLinkHandled.current=true;const params=new URLSearchParams(window.location.search);const id=params.get('recipe');if(id)void openRecipeId(id);},[data?.recipes.length]);
useEffect(()=>{if(data?.profile.id)setHasDraft(!!readDraft(localStorage,data.profile.id));},[data?.profile.id,editor===null]);
useEffect(()=>{if(!editor||!data?.profile.id)return;if(![editor.title,editor.description,editor.ingredients,editor.steps].some(v=>v?.trim())&&editor.image==='none'){removeDraft(localStorage,data.profile.id,editor.id);if(!editor.id)setHasDraft(false);setDraftSaved(false);return;}const saved=writeDraft(localStorage,data.profile.id,editor);setDraftSaved(saved);if(!editor.id)setHasDraft(saved);},[editor,data?.profile.id]);
function go(v:string){setView(v);setQuery('');setAuthorFilter('');window.scrollTo({top:0,behavior:'smooth'});}
async function saveRecipe(r:Recipe){await act(async()=>{const j=await api({op:'save',recipe:r.id});await refreshAll();flash(j.already?'すでにあなたの棚に保存されています。':'あなたの棚に保存しました。作者へのつながりも引き継ぎます。');});}
function cook(r:Recipe){setSelected(null);setCookRecipe(r);}
async function bindWallet(){await act(async()=>{const p=walletProvider();await p.connect();if(!p.signMessage)throw Error('メッセージ署名に対応したウォレットをご利用ください。');const wallet=p.publicKey.toString(),c=await api({op:'challenge',wallet});const result=await p.signMessage(new TextEncoder().encode(c.message),'utf8');const bytes=result.signature||result;await api({op:'bindWallet',id:c.id,signature:btoa(String.fromCharCode(...bytes))});await load();flash('署名を確認してウォレットを連携しました。');});}
function openRecipe(r:Recipe){setSelected(r);setChecks([]);setReport(false);setShareFallback('');}
function edit(r?:Recipe){const draft=data&&readDraft(localStorage,data.profile.id,r?.id);setSelected(null);setEditor(draft?{...blank,...r,...draft,version:draft.version??0}:r?{...r}:{...blank});setDraftSaved(!!draft);setConsent(false);setSimilar([]);setAiStatus(draft?'この端末の下書きを復元しました。':'');setAiError('');setAiCleanupAvailable(false);setAiTask('compose');setAiSuggestion(null);setUndoDraft(null);}
async function closeEditor(){await act(async()=>{const hasContent=!!editor&&([editor.title,editor.description,editor.ingredients,editor.steps].some(v=>v?.trim())||editor.image!=='none');const synced=await cloud.flush();if(!synced&&!draftSaved&&hasContent&&!confirm('この端末にもクラウドにも保存できませんでした。入力を破棄して閉じますか？'))return;setEditor(null);setAiSuggestion(null);if(synced){await community.load();if(draftSaved||hasContent)flash('下書きを保存しました。同じアカウントなら別の端末から再開できます。');}else if(draftSaved)flash('この端末に下書きを保存しました。クラウドは未同期です。同じ端末で続けてください。');else if(hasContent)flash('未保存の入力を破棄して閉じました。');});}
async function discardDraft(){if(!data||!editor||!confirm('この下書きと未公開の入力を破棄しますか？公開済みの原本は変わりません。'))return;await act(async()=>{if(!await cloud.clear()){flash('別の端末の変更を確認し、下書きを再度選んでください。削除は行っていません。','error');return;}if(!removeDraft(localStorage,data.profile.id,editor.id)){flash('この端末の下書きを削除できませんでした。','error');return;}if(!editor.id)setHasDraft(false);setEditor(null);setAiSuggestion(null);});}
function openImport(){setAiStatus('');setAiError('');setImportOpen(true);}
async function signOut(){await act(async()=>{const {error}=await supabase.auth.signOut({scope:'local'});if(error)throw Error('ログアウトできませんでした。もう一度お試しください。');});}
function clearFilters(){setQuery('');setCategory('すべて');setAuthorFilter('');}

async function publish(ack=false){const issue=recipeIssue(editor);if(issue){flash(issue);return;}await act(async()=>{try{if(!await cloud.flush())throw Error('下書きの同期を確認してから公開してください。');await api({op:'publish',...editor,consent,acknowledgeSimilarity:ack});const cleared=await cloud.clear();removeDraft(localStorage,data!.profile.id,editor.id);if(!editor.id)setHasDraft(false);await refreshAll();setEditor(null);setSimilar([]);go('creator');flash(cleared?'レシピを公開しました。次にウォレットと外部投稿を紐づけられます。':'公開しました。別の端末に残った下書きは、確認してから削除してください。');}catch(e){if((e as any).similar)setSimilar((e as any).similar);if((e as any).publicationConflict)setPublicationConflict((e as any).current);throw e;}});}
async function upload(file:File){await act(async()=>{if(file.size>2097152)throw Error('画像は2MB以下にしてください。');const r=await apiFetch('/api/photo',{method:'POST',headers:{'Content-Type':file.type},body:file});const j:any=await r.json();if(!r.ok)throw Error(j.error);setEditor((p:any)=>({...p,image:'photo:'+j.id}));flash('写真を保存しました。');});}
async function aiDraft(mode:'publish'|'import',action:'compose'|'refine'='compose'){setAiTask(mode==='import'?'import':action);setAiError('');setAiCleanupAvailable(false);await act(async()=>{setAiStatus(mode==='import'?'Gemini Flashで抽出しています…':action==='compose'?'こだわりを食材と調理法に反映しています…':'材料・分量・作り方を整えています…');try{if(mode==='publish'){if(![editor.title,editor.description,editor.ingredients,editor.steps].some(v=>v?.trim()))throw Error('料理名・こだわりポイント・食材のどれかを入力してください。');setAiSuggestion(null);const r=await apiFetch('/api/extract',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,recipe:{title:editor.title,description:editor.description,ingredients:editor.ingredients,steps:editor.steps,servings:editor.servings,minutes:editor.minutes,category:editor.category}})});const parsed:any=await r.json();if(!r.ok)throw Object.assign(Error(parsed.error||'レシピ案を作れませんでした。'),{status:r.status});if(!parsed.draft?.ingredients||!parsed.draft?.steps)throw Error('AIの応答を読み取れませんでした。');setAiSuggestion({draft:parsed.draft,warnings:Array.isArray(parsed.warnings)?parsed.warnings:[],mode:action});setAiStatus('AIの案ができました。下の内容を確認して反映してください。');}else{if(!importForm.notes.trim()&&!importMedia.length&&!isHttpsUrl(importForm.url))throw Error('投稿URL・材料や手順のメモ・画像のどれかを入力してください。');const r=await apiFetch('/api/extract',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sourceUrl:importForm.url.trim(),sharedText:importForm.notes||'',images:importMedia})});const parsed:any=await r.json();if(!r.ok)throw Object.assign(Error(parsed.error||'抽出できませんでした。'),{status:r.status});const amount=(x:any)=>['大さじ','小さじ'].includes(x.unit)?x.unit+x.quantity:[x.quantity,x.unit].filter(Boolean).join('');const patch={title:parsed.name||importForm.title,ingredients:(parsed.ingredients||[]).map((x:any)=>[x.name,amount(x)].filter(Boolean).join(' ')).join('\n'),steps:(parsed.steps||[]).join('\n')};setImportForm(p=>({...p,...patch}));setAiStatus('Gemini Flashで抽出しました。元の投稿と照合して確認してください。');}}catch(e){setAiStatus('');setAiError((e as Error).message);setAiCleanupAvailable(e instanceof TypeError||[429,502,503,504].includes(Number((e as any).status)));throw e;}});}
function applyAiSuggestion(){if(!aiSuggestion||!editor)return;setUndoDraft({...editor});setEditor({...editor,...aiSuggestion.draft});setAiSuggestion(null);setConsent(false);setAiError('');setAiStatus(aiSuggestion.source==='input_cleanup'?'入力の表記整理を反映しました（AI未使用）。':'AIの案を反映しました。材料・分量・加熱方法を確認して編集してください。');}
function undoAiSuggestion(){if(!undoDraft)return;setEditor((p:any)=>({...p,...undoDraft}));setUndoDraft(null);setConsent(false);setAiStatus('反映する前の内容に戻しました。');}
async function anchor(r:Recipe){await act(async()=>{if(!data?.profile.wallet)throw Error('プロフィールから先にウォレットを署名で連携してください。');const p=walletProvider();await p.connect();if(p.publicKey.toString()!==data.profile.wallet)throw Error('連携済みのウォレットに切り替えてください。');const expected=await sha256(recipeDocument(r));if(expected!==r.hash)throw Error('内容が更新されています。再読み込みしてください。');const key='tsukurite-anchor-'+r.id+'-'+r.version;let signature=localStorage.getItem(key);if(!signature){if(!confirm('Solana Devnetに登録します。ウォレットアドレスとレシピID・ハッシュが公開され、テストSOLの手数料を使います。続けますか？'))return;const sent=await sendDevnet({memo:'TSUKURITE:v1:'+r.id+':'+r.hash});signature=sent.signature;localStorage.setItem(key,signature);flash('送信しました。確認中です。再送しないでください。');try{await sent.confirm();}catch{}}const j=await api({op:'anchor',recipe:r.id,signature});if(j.pending){flash('送信済みです。ネットワーク反映後に「記録・再確認」を押してください。');return;}localStorage.removeItem(key);await load();flash('Devnetで原本の記録を確認しました。著作権の認定ではありません。');});}
async function sendTest(){await act(async()=>{if(!data?.profile.wallet)throw Error('先にウォレットを連携してください。');if(!recipient.trim())throw Error('テストの送付先を入力してください。');const p=walletProvider();await p.connect();if(p.publicKey.toString()!==data.profile.wallet)throw Error('連携したウォレットに切り替えてください。');if(!confirm('DevnetのテストSOLを0.0001 SOL送ります。実際の報酬ではありません。送付先：'+recipient))return;const intent=await api({op:'transferIntent',recipient,kind:'test'});const pendingKey='tsukurite-transfer-'+intent.id;try{const sent=await sendDevnet({memo:'TSUKURITE:devnet:'+intent.id,recipient:intent.recipient,amount:intent.amount});localStorage.setItem(pendingKey,sent.signature);flash('送信済みです。確認中です。');await api({op:'transferSubmitted',id:intent.id,signature:sent.signature});try{await sent.confirm();}catch{}const result=await api({op:'transferConfirm',id:intent.id,signature:sent.signature});if(!result.pending){localStorage.removeItem(pendingKey);flash('Devnetでテスト送金を確認しました。');}else flash('送信済みです。履歴から再確認してください。');await load();setTestTransfer(false);}catch(e){await load();throw e;}});}
async function sendReward(row:any){await act(async()=>{if(!data?.profile.wallet)throw Error('資金提供側のウォレットを先に署名で連携してください。');const p=walletProvider();await p.connect();if(p.publicKey.toString()!==data.profile.wallet)throw Error('連携したウォレットに切り替えてください。');if(!confirm(row.name+'へ、試算した'+row.amount/1e9+'テストSOLをあなたの接続ウォレットから送ります。実売上に基づく報酬ではありません。送付先：'+row.wallet))return;const intent=await api({op:'transferIntent',recipient:row.wallet,kind:'reward',author:row.owner});try{const sent=await sendDevnet({memo:'TSUKURITE:devnet:'+intent.id,recipient:intent.recipient,amount:intent.amount});localStorage.setItem('tsukurite-transfer-'+intent.id,sent.signature);await api({op:'transferSubmitted',id:intent.id,signature:sent.signature});try{await sent.confirm();}catch{}const j=await api({op:'transferConfirm',id:intent.id,signature:sent.signature});flash(j.pending?'送信済みです。履歴から再確認してください。':'試算額のDevnetテスト分配を確認しました。');await load();}catch(e){await load();throw e;}});}
async function retryTransfer(t:any){await act(async()=>{const signature=t.signature||localStorage.getItem('tsukurite-transfer-'+t.id);if(!signature)throw Error('署名済みの取引IDがありません。未送信なら予定を取り消せます。');const j=await api({op:'transferConfirm',id:t.id,signature});if(j.pending)flash('反映待ちです。Explorerでも確認してください。');else{localStorage.removeItem('tsukurite-transfer-'+t.id);flash('送金を確認しました。');}await load();});}
async function checkVersion(v:any){const computed=await sha256(v.snapshot);if(computed!==v.hash){flash('保存内容とハッシュが一致しません。');return;}const current=data?.recipes.find(r=>r.id===v.recipe);const same=current&&await sha256(recipeDocument(current))===v.hash;flash('保存内容とSHA-256が一致しました。'+(same?'現在の版と同じ内容です。':'現在の版とは異なる、改訂前の内容です。'));}
async function exportData(){await act(async()=>{const [extra,r]=await Promise.all([communityApi({op:'export'},data?.profile.id),apiFetch('/api/app?action=export')]);const all=await r.json();if(!r.ok)throw Error(all.error||'書き出せませんでした。');const blob=new Blob([JSON.stringify({format:'tsukurite-export-v3',exportedAt:new Date().toISOString(),...all,community:extra},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='tsukurite-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);});}
async function copyLink(r:Recipe){const link=window.location.origin+'/r/'+encodeURIComponent(r.id);try{await navigator.clipboard.writeText(link);setShareFallback('');flash('原本へのリンクをコピーしました。SNS投稿に添えられます。');}catch{setShareFallback(link);flash('コピーできませんでした。表示したリンクを長押ししてコピーしてください。');}}
const own=data?.recipes.filter(r=>r.owner===data.profile.id)||[],published=data?.recipes.filter(r=>r.status==='published')||[];
const list=feed.recipes;
const shelfList=(data?.shelf||[]).filter(item=>{const recipe=data?.recipes.find(r=>r.id===item.recipe);return matchesSearch(query,item.title,item.notes,item.ingredients,item.steps,recipe?.title,recipe?.ingredients,recipe?.authorName);});
const editorIssue=editor?recipeIssue(editor):'';
const saved=(r:Recipe)=>!!data?.shelf.some(s=>s.recipe===r.id);
const cookedToday=(r:Recipe)=>!!data?.myEvents.some(e=>e.recipe===r.id&&e.kind==='cook'&&e.day===new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Tokyo'}).format(new Date()));

const navs=[['discover','レシピを見つける',<LayoutGrid size={19} key="i"/>],['timeline','つながり',<Users size={19} key="i"/>],['planner','献立・買い物',<CalendarDays size={19} key="i"/>],['shelf','わたしのレシピ棚',<Library size={19} key="i"/>],['creator','レシピを発信',<PenLine size={19} key="i"/>],['rewards','収益とつながり',<Coins size={19} key="i"/>]];
const recipeCard=(r:Recipe)=><article key={r.id} className="recipe-card"><div className="image-button"><button className="photo-open" aria-label={r.title+'の詳細を開く'} onClick={()=>openRecipe(r)}><Food image={r.image}/></button><span className="time-pill"><Clock size={12}/>{r.minutes}分</span><button className="image-save" disabled={busy||saved(r)} aria-pressed={saved(r)} onClick={()=>saveRecipe(r)} aria-label={r.title+(saved(r)?'は棚に保存済み':'を棚に保存')}><Bookmark size={18} fill={saved(r)?'currentColor':'none'}/></button></div><div className="recipe-card-body"><div className="recipe-labels"><span>{r.category}</span>{r.sample?<span className="sample">体験用サンプル</span>:<span className="original"><Leaf size={10}/>オリジナル投稿</span>}</div><button className="recipe-title" onClick={()=>openRecipe(r)}>{r.title}</button><div className="card-author-row"><button className="author-link" onClick={()=>{clearFilters();setAuthorFilter(r.owner);setView('discover');window.scrollTo({top:0,behavior:'smooth'});}}><Avatar name={r.authorName}/>{r.authorName}<ChevronRight size={12}/></button>{data&&<FollowButton author={r.owner} state={community.data} user={data.profile.id} onChanged={community.load} onError={communityError}/>}</div><div className="card-stats"><span><Bookmark size={13}/>{r.saves||0} 保存</span><span><ChefHat size={14}/>{r.cooks||0} 作った</span>{r.chainStatus==='confirmed'&&<span className="green"><ShieldCheck size={13}/>記録済み</span>}</div></div></article>;

return <div className="app-shell"><aside className="sidebar"><button className="brand" onClick={()=>go('discover')}><span className="brand-mark"><ChefHat size={25}/></span><span>つくりて<small>TSUKURITE</small></span></button><p className="side-label">YOUR DAILY KITCHEN</p><nav>{navs.map(([key,label,icon])=><button key={key as string} className={view===key?'active':''} aria-current={view===key?'page':undefined} onClick={()=>go(key as string)}>{icon}{label}</button>)}</nav><button className="side-post" onClick={()=>edit()}><Plus size={18}/>レシピを発信する</button><div className="sidebar-story"><Leaf size={23}/><b>あなたの「おいしい」が、<br/>誰かの力になる。</b><p>保存して、作って。<br/>その先にいる作者へ、価値を。</p><button onClick={()=>setHelp(true)}>つくりての仕組み <ArrowRight size={14}/></button></div><div className="side-bottom"><button className={view==='profile'?'active':''} onClick={()=>go('profile')}><Settings size={17}/>プロフィール・設定</button><span><i/> SOLANA DEVNET</span></div></aside>
<div className="content-shell"><header className="topbar"><div className="mobile-logo"><ChefHat size={22}/>つくりて</div><label className="searchbox"><Search size={18}/><input aria-label="レシピを検索" type="search" placeholder="料理名・食材・作者で検索" value={query} onChange={e=>{setQuery(e.target.value);if(view!=='discover'&&view!=='shelf')setView('discover');}}/></label><div className="top-actions"><span className="beta-pill">DEMO</span><button className="notification-button" aria-label={'お知らせ（未読'+(community.data?.unread||0)+'件）'} onClick={()=>setNotificationOpen(true)}><Bell size={19}/>{!!community.data?.unread&&<span className="notification-count">{community.data.unread>99?'99+':community.data.unread}</span>}</button><button className="wallet-button" onClick={()=>go('profile')}><Wallet size={16}/>{data?.profile.wallet?data.profile.wallet.slice(0,4)+'…'+data.profile.wallet.slice(-4):'ウォレット（任意）'}</button><button className="profile-button" aria-label="プロフィール" onClick={()=>go('profile')}><Avatar name={data?.profile.name||'あ'}/></button></div></header><div className="mobile-nav">{navs.filter(([key])=>key!=='rewards').map(([k,l,i])=><button key={k as string} className={view===k?'active':''} aria-current={view===k?'page':undefined} onClick={()=>go(k as string)}>{i}<span>{String(l).replace('レシピを発信','発信').replace('レシピを見つける','見つける').replace('わたしのレシピ棚','レシピ棚').replace('収益とつながり','収益').replace('献立・買い物','献立')}</span></button>)}</div>
{error&&<div className="error-banner"><AlertCircle size={18}/>{error}<button onClick={load}>再試行</button></div>}{signIn&&<div className="signin-state"><h1>ログイン期限が切れました</h1><button className="primary" onClick={()=>supabase.auth.signOut({scope:'local'})}>もう一度ログイン</button></div>}
{!data&&!signIn&&!error&&<div className="loading"><LoaderCircle className="spin"/>キッチンを準備しています…</div>}
{data&&!signIn&&<main>{community.error&&<div className="community-error" role="alert">{community.error}<button onClick={community.load}>再読み込み</button></div>}
{view==='timeline'&&<Timeline state={community.data} recipes={data.recipes} renderRecipe={recipeCard} onOpenRecipe={openRecipeId} user={data.profile.id} onChanged={refreshAll} onError={communityError}/>}
{view==='planner'&&<MealPlanner user={data.profile.id} week={week} setWeek={setWeek} state={community.data} recipes={data.recipes} shelf={data.shelf} onChanged={community.load} onError={communityError} onOpenRecipe={openRecipeId}/>}
{(view==='discover'||view==='shelf')&&<label className="mobile-search"><Search size={17}/><input aria-label="レシピを検索（スマホ）" type="search" placeholder="料理名・食材で検索" value={query} onChange={e=>{setQuery(e.target.value);if(view!=='discover'&&view!=='shelf')setView('discover');}}/></label>}
{view==='discover'&&<>{!query.trim()&&!authorFilter&&<section className="hero"><div className="hero-copy"><span className="eyebrow"><span/> GOOD FOOD, SHARED VALUE.</span><h1>今日の「おいしい」が、<br/>誰かの<span>力になる。</span></h1><p>ひらめきの一皿を、毎日の食卓へ。</p><div className="hero-buttons"><button className="primary browse-button" onClick={()=>document.getElementById('recipe-feed')?.scrollIntoView({behavior:'smooth'})}><Search size={16}/>レシピを探す</button><button className="secondary" onClick={()=>edit()}><Plus size={16}/>レシピを発信 <ArrowUpRight size={16}/></button><button className="hero-secondary" onClick={()=>setHelp(true)}>仕組みを知る <ArrowRight size={15}/></button></div><div className="hero-note"><ShieldCheck size={14}/>ウォレットなしで、保存・公開できます。</div></div><div className="hero-photo"><Food image="grid:0"/><span className="hero-photo-label">A LITTLE INSPIRATION<br/><b>いつもの食卓に、ひと工夫。</b></span><div className="floating-card"><span className="floating-icon"><ChefHat size={20}/></span><div><b>作るよろこびを、作者にも。</b><small>レシピがつなぐ、新しい循環。</small></div><ArrowUpRight size={17}/></div></div></section>}{!query.trim()&&!authorFilter&&<section className="value-strip"><span><Bookmark size={17}/>ひらめきを、あなたの棚へ</span><span><ChefHat size={18}/>作ったら、気持ちを届ける</span><span><Leaf size={18}/>役立つほど、作者に価値が返る</span></section>}<section id="recipe-feed" className="feed-section"><div className="section-heading"><div><p className="eyebrow">FIND YOUR NEXT FAVORITE</p><h2>{authorFilter?published.find(r=>r.owner===authorFilter)?.authorName+'のレシピ':'今日、なに作る？'}<span>{list.length}</span></h2></div><button className="subtle" onClick={openImport}><Link2 size={16}/>外部レシピを取り込む <ArrowUpRight size={14}/></button></div><div className="feed-controls"><div className="categories">{categories.map(c=><button key={c} className={category===c?'selected':''} aria-pressed={category===c} onClick={()=>setCategory(c)}>{c==='すべて'&&<LayoutGrid size={13}/>}{c}</button>)}</div><label className="sort"><SlidersHorizontal size={14}/><select aria-label="並べ替え" value={sort} onChange={e=>setSort(e.target.value)}><option value="new">新しい順</option><option value="saved">保存が多い順</option></select></label></div>{(query.trim()||category!=='すべて')&&<div className="search-summary" role="status"><span>{query.trim()?`「${query.trim()}」の検索結果`:'絞り込み結果'} · {list.length}件</span><button className="text-link" onClick={clearFilters}>条件をクリア</button></div>}{authorFilter&&<button className="text-link" onClick={()=>setAuthorFilter('')}>作者の絞り込みを解除</button>}<div className="recipe-grid">{list.map(recipeCard)}</div><div className="feed-pagination">{feed.loading&&<p role="status">レシピを読み込み中…</p>}{feed.error&&<div role="alert"><p>{feed.error}</p><button className="secondary" onClick={feed.reload}>再読み込み</button></div>}{feed.cursor&&!feed.error&&<button className="secondary" disabled={feed.loading} onClick={feed.more}>さらにレシピを見る</button>}</div>{!list.length&&!feed.loading&&!feed.error&&<div className="empty"><Search size={35}/><h3>ぴったりの一皿を探そう。</h3><p>検索条件やカテゴリーを変えてみてください。</p><button className="secondary" onClick={clearFilters}>すべてのレシピを表示</button></div>}<p className="sample-note">サンプルの作者・レシピは体験用です。写真はAI生成。実際の保存・調理件数を表示し、収益分配には含めません。</p></section></>}
{view==='shelf'&&<><PageTitle eyebrow="YOUR RECIPE SHELF" title="わたしのレシピ棚" text="SNSで出会った一皿も、あなたの日々の定番も。"/><div className="page-actions"><button className="primary" onClick={openImport}><Link2 size={16}/>外部から取り込む</button><span className="muted">{data.shelf.length}件 · 外部メモはあなただけに表示</span></div><div className="recipe-grid">{shelfList.map(s=>{const r=data.recipes.find(r=>r.id===s.recipe&&r.status==='published');return r?<div key={s.id}>{recipeCard(r)}<button className="remove-link" onClick={()=>act(async()=>{await api({op:'removeShelf',id:s.id});await load();})}>棚から外す</button></div>:<article key={s.id} className="external-card"><div className="external-top"><Link2 size={25}/><span className="badge">自分用 · 分配対象外</span></div><h3>{s.title}</h3><p>{s.url.startsWith('app:')?'現在、原本は非公開です。':new URL(s.url).hostname}</p><p>{s.notes.slice(0,80)||'出典付きの外部メモ。作者の原本と確認できた場合のみ収益対象につながります。'}</p><button className="secondary" onClick={()=>{setChecks([]);setPrivateItem(s);}}>メモを開く <ArrowUpRight size={15}/></button><button className="remove-link" onClick={()=>act(async()=>{await api({op:'removeShelf',id:s.id});await load();})}>棚から外す</button></article>;})}</div>{!!data.shelf.length&&!shelfList.length&&<div className="empty"><Search size={35}/><h3>棚に一致するレシピがありません。</h3><p>料理名や食材を変えて検索してみてください。</p><button className="secondary" onClick={()=>setQuery('')}>検索をクリア</button></div>}{!data.shelf.length&&<div className="empty"><Library size={45}/><h3>あなたの棚は、これから。</h3><p>気になるレシピの保存ボタンを押してみましょう。</p><button className="secondary" onClick={()=>go('discover')}>レシピを見つける <ArrowRight size={15}/></button></div>}</>}
{view==='shelf'&&<PrivateVariants variants={community.data?.variants||[]} user={data.profile.id} onChanged={community.load} onError={communityError} onOpenRecipe={openRecipeId}/>}
{view==='creator'&&<><PageTitle eyebrow="CREATOR STUDIO" title="ひらめきを、届けよう。" text="あなたのレシピから、おいしいの循環がはじまります。"/>{!!community.data?.drafts.length&&<section className="synced-drafts"><h3>同期した下書き</h3>{community.data.drafts.map(d=><div key={d.draft_key} className="synced-draft-row"><div><b>{d.title||'タイトル未入力'}</b><small>{new Date(d.updated_at).toLocaleString('ja-JP')}</small></div><button className="secondary" onClick={()=>{if(d.draft_key==='new')edit();else{const r=own.find(r=>r.id===d.draft_key);if(r)edit(r);else flash('元のレシピを読み込めませんでした。','error');}}}>続きを書く</button></div>)}</section>}{hasDraft&&!community.data?.drafts.some(d=>d.draft_key==='new')&&<div className="draft-banner"><div><b>書きかけのレシピがあります</b><p>この端末の下書きから再開して、クラウドに同期できます。</p></div><button className="secondary" onClick={()=>edit()}>下書きの続きを書く</button></div>}<div className="creator-intro"><div><PenLine size={28}/><h3>あなたの工夫が、誰かの定番に。</h3><p>自作の説明・写真を投稿し、他の人が保存・調理できる原本をつくります。</p></div><button className="primary" onClick={()=>edit()}><Plus size={16}/>レシピを発信する</button></div><div className="section-heading"><h2>あなたの原本 <span>{own.length}</span></h2><button className="subtle" disabled={!own.some(r=>r.status==='published')} onClick={()=>setSourceOpen(true)}><Link2 size={16}/>外部SNSを紐づける</button></div><div className="creator-list">{own.map(r=><article className="creator-row" key={r.id}><Food image={r.image}/><div><span className="eyebrow">VERSION {r.version} · {r.status==='published'?'公開中':'非公開'}</span><h3>{r.title}</h3><p>{r.saves} 保存 · {r.cooks} 作った · {r.chainStatus==='confirmed'?'Devnet記録済み':'チェーン未記録'}</p></div><div className="row-actions"><button className="secondary" onClick={()=>edit(r)}>編集</button><button className="secondary" disabled={busy||r.chainStatus==='confirmed'} onClick={()=>anchor(r)}><ShieldCheck size={14}/>{r.chainStatus==='confirmed'?'記録済み':'記録・再確認'}</button><button className="icon-button" aria-label="共有リンクをコピー" onClick={()=>copyLink(r)}><Copy size={16}/></button>{r.status==='published'&&<button className="text-link" onClick={()=>{if(confirm('この原本を非公開にしますか？チェーンに記録済みの履歴は残ります。'))act(async()=>{await api({op:'archive',recipe:r.id});await load();});}}>非公開</button>}</div></article>)}</div>{!own.length&&<div className="empty"><PenLine size={40}/><h3>最初の一皿を、公開してみよう。</h3><p>入力したレシピは、新アプリ専用の保存先に残ります。</p></div>}<div className="two-column"><section className="panel"><div className="panel-title"><Link2 size={20}/><h3>外部SNSとのつながり</h3></div><p>外部投稿の管理を確認できたURLだけ、取り込み時に原本へつなぎます。</p>{data.sources.map(s=><div className="source-item" key={s.id}><span className={'badge '+(s.status==='verified'?'green':'')}>{s.status==='verified'?'投稿管理を確認済み':'未確認・自動連携なし'}</span><a href={s.url} target="_blank" rel="noopener noreferrer">{s.url}<ExternalLink size={12}/></a><code>{s.code}</code><small>このコードを投稿のタイトル・キャプションに掲載してください。</small><button className="secondary" disabled={busy||s.status==='verified'} onClick={()=>act(async()=>{await api({op:'sourceVerify',id:s.id});await load();flash('公開投稿の確認コードを照合しました。');})}>公開投稿を再確認</button></div>)}{!data.sources.length&&<p className="muted">まだ紐づけた投稿はありません。</p>}<button className="text-link" disabled={!own.some(r=>r.status==='published')} onClick={()=>setSourceOpen(true)}>＋ 外部投稿を登録する</button>{!own.some(r=>r.status==='published')&&<p className="field-help">自作レシピの公開後に紐づけられます。</p>}</section><section className="panel"><div className="panel-title"><ShieldCheck size={20}/><h3>原本と改訂履歴</h3></div><p>レシピ本文のハッシュと登録ウォレットを照合します。登録順が著作者を決める仕組みではありません。</p>{data.versions.map(v=><div className="version-item" key={v.id}><b>{JSON.parse(v.snapshot).title} · v{v.version}</b><code>SHA-256 {v.hash}</code><button className="text-link" onClick={()=>checkVersion(v)}>保存内容を照合</button><details><summary>この版の材料・手順</summary><p className="pre-line">{JSON.parse(v.snapshot).ingredients}</p><p className="pre-line">{JSON.parse(v.snapshot).steps}</p></details><span>{v.chain_status==='confirmed'?'確認済み':'未記録'} · {new Date(v.created).toLocaleDateString('ja-JP')}</span>{v.signature&&<a className="text-link" href={explorer(v.signature)} target="_blank" rel="noopener noreferrer">Explorerで照合 <ExternalLink size={12}/></a>}</div>)}</section></div></>}
{view==='rewards'&&<><PageTitle eyebrow="VALUE RETURNS TO THE CREATOR" title="おいしいが、作者に返る。" text="保存と調理のつながりを、作者の次のひらめきへ。"/><div className="test-notice"><Info size={20}/><div><b>Devnetで仕組みを試す、テスト運用です。</b><p>広告・サブスクリプションの課金は未接続です。表示額は仮の分配枠による試算で、実際の売上・支払保証・円の報酬ではありません。</p></div></div><div className="stats-grid"><div className="stat-card"><span>今月のあなたの有効ポイント</span><strong>{data.rewards.myPoints}<small>pt</small></strong><p>自分・サンプルへの操作は対象外</p></div><div className="stat-card"><span>テスト分配額の試算</span><strong>{(data.rewards.estimateLamports/1e9).toFixed(6)}<small>テストSOL</small></strong><p>変動する試算 · 未確定</p></div><div className="stat-card"><span>今月の全体ポイント</span><strong>{data.rewards.totalPoints}<small>pt</small></strong><p>{data.rewards.period} / 保存1pt・調理報告3pt</p></div></div><div className="two-column"><section className="panel simulation"><p className="eyebrow">TRY THE DISTRIBUTION</p><h3>もし、あなたのレシピが使われたら。</h3><p>入力した数字で分配を試算できます。実際の利用件数には加算しません。</p><label>有効な保存数<input type="number" min="0" max="10000" value={testSaves} onChange={e=>setTestSaves(Math.min(10000,Math.max(0,Number(e.target.value))))}/></label><label>有効な調理報告数<input type="number" min="0" max="10000" value={testCooks} onChange={e=>setTestCooks(Math.min(10000,Math.max(0,Number(e.target.value))))}/></label><div className="calculation"><span>{testSaves} + {testCooks} × 3 = <b>{testSaves+testCooks*3} pt</b></span><strong>{((testSaves+testCooks*3)/(100+testSaves+testCooks*3)*.001).toFixed(6)} <small>テストSOL</small></strong><small>仮定：他の作者100pt、分配枠0.001テストSOL</small></div></section><section className="panel"><p className="eyebrow">SOLANA CONNECTION</p><h3>あなたのウォレットへ、直接。</h3><p>署名でウォレットを紐づけて、Devnetで少額の送金を試せます。テスト送金は上の収益試算とは別です。</p><div className="wallet-detail"><Wallet size={22}/><code>{data.profile.wallet||'ウォレット未接続'}</code></div><div className="stack-buttons"><button className="primary" disabled={busy} onClick={bindWallet}><Wallet size={16}/>ウォレットを署名で連携</button><button className="secondary" onClick={()=>{setRecipient(data.profile.wallet||'');setTestTransfer(true);}}>Devnetの送金を試す <ArrowUpRight size={15}/></button><a className="text-link" href="https://faucet.solana.com/" target="_blank" rel="noopener noreferrer">DevnetのテストSOLを取得 <ExternalLink size={13}/></a></div><small className="muted">秘密鍵は保存しません。送金元は接続したウォレットで、資金は運営から自動供給されません。</small></section></div><section className="panel"><h3>試算額のテスト分配</h3><p>資金を提供する人が、自分の接続ウォレットから作者へ送るDevnetの実演です。月のテスト分配枠を超える予約と、同じ作者への同月の重複分配を防ぎます。</p>{!(data.rewards.allocations||[]).length&&<p className="muted">他の人による有効な保存・調理報告が入ると、作者ごとの試算が表示されます。自己利用・サンプル・未連携の外部メモは対象外です。</p>}{(data.rewards.allocations||[]).map((row:any)=><div className="transfer-row" key={row.owner}><div><b>{row.name}</b><p>{row.points} pt · {row.amount/1e9} テストSOL</p></div><button className="secondary" disabled={busy||!row.wallet||!data.profile.wallet} onClick={()=>sendReward(row)}>{row.wallet?'試算額をDevnetで分配':'作者のウォレット未連携'}</button></div>)}</section><section className="panel"><h3>Devnetの送金履歴</h3>{!data.transfers.length&&<p>まだ送金履歴はありません。</p>}{data.transfers.map(t=><div className="transfer-row" key={t.id}><div><b>{t.kind==='reward'?'テスト分配':'接続確認用のテスト送金'}</b><p>{t.amount/1e9} テストSOL → {t.recipient.slice(0,5)}…{t.recipient.slice(-5)}</p></div><span className="badge">{t.status==='confirmed'?'確認済み':t.status==='cancelled'?'取り消し':'未確認'}</span>{t.signature&&<a className="text-link" href={explorer(t.signature)} target="_blank" rel="noopener noreferrer">Explorer <ExternalLink size={12}/></a>}{t.status==='pending'&&<button className="secondary" disabled={busy} onClick={()=>retryTransfer(t)}>状態を再確認</button>}{t.status==='pending'&&!t.signature&&<button className="text-link" disabled={busy} onClick={()=>act(async()=>{await api({op:'cancelIntent',id:t.id});await load();})}>未送信の予定を取り消す</button>}</div>)}</section><p className="sample-note">実際の配分を確定する機能は、広告収入の接続、不正対策、作者との契約・支払い条件の整備後に運用します。</p></>}
{view==='profile'&&<><PageTitle eyebrow="YOUR KITCHEN, YOUR IDENTITY" title="プロフィール・設定" text="つくりてとしての名前と、あなたのデータ。"/><div className="two-column"><section className="panel"><label>公開する名前<input value={profileForm.name} maxLength={40} onChange={e=>setProfileForm(p=>({...p,name:e.target.value}))}/></label><label>自己紹介<textarea rows={4} maxLength={300} value={profileForm.bio} onChange={e=>setProfileForm(p=>({...p,bio:e.target.value}))}/></label><button className="primary" disabled={busy||!profileForm.name.trim()} onClick={()=>act(async()=>{await api({op:'profile',...profileForm});await load();flash('プロフィールを保存しました。');})}>プロフィールを保存</button></section><section className="panel"><h3>データとウォレット</h3><button className="secondary" onClick={()=>go('rewards')}><Coins size={17}/>収益とSolanaのつながりを見る</button><p>このアプリ専用の保存先を使います。既存のれしぴ棚のデータにはアクセスしません。</p><button className="secondary" onClick={exportData}><Download size={16}/>自分のデータを書き出す</button><div className="divider"/><h4>ウォレット連携</h4><code className="wallet-code">{data.profile.wallet||'未接続'}</code><button className="secondary" disabled={busy} onClick={bindWallet}><Wallet size={16}/>署名して接続</button><p className="muted">ウォレットなしでもレシピの閲覧・保存・公開ができます。</p><button className="text-link" onClick={()=>setHelp(true)}>利用ルール・収益の仕組み</button><div className="divider"/><h4>アカウント</h4><button className="secondary" disabled={busy} onClick={signOut}>ログアウト</button><p className="field-help">この端末の下書きは残ります。共用端末では公開前の内容にもご注意ください。</p></section></div><AccountRecovery/></>}
<footer><span className="footer-brand"><ChefHat size={17}/>つくりて</span><span>おいしいが、めぐる場所。</span><button onClick={()=>setHelp(true)}>仕組み・利用ルール</button><small><i/> Devnet · Demo</small></footer></main>}
</div>
{selected&&<Modal busy={busy} title="レシピの原本" wide onClose={()=>setSelected(null)}><div className="recipe-detail"><div><Food image={selected.image} className="detail-photo"/><div className="detail-copy"><div className="recipe-labels"><span>{selected.category}</span><span>{selected.sample?'体験用サンプル':'オリジナル投稿'} · v{selected.version}</span></div><h2>{selected.title}</h2><div className="detail-community"><div className="author-link"><Avatar name={selected.authorName}/>{selected.authorName}</div>{data&&<FollowButton author={selected.owner} state={community.data} user={data.profile.id} onChanged={community.load} onError={communityError}/>}</div><p>{selected.description}</p><div className="detail-meta"><span><Clock size={16}/>{selected.minutes}分</span><span><Users size={16}/>{selected.servings}人分</span></div><h3>材料</h3><ul className="ingredients">{selected.ingredients.split('\n').filter(Boolean).map((v,i)=><li key={i}><Leaf size={13}/>{v}</li>)}</ul><h3>つくり方 <small>手順をチェックできます</small></h3><ol className="steps-list">{selected.steps.split('\n').filter(Boolean).map((v,i)=><li key={i} className={checks.includes(i)?'checked':''}><button aria-pressed={checks.includes(i)} aria-label={'手順'+(i+1)+(checks.includes(i)?'のチェックを外す':'をチェック')} onClick={()=>setChecks(p=>p.includes(i)?p.filter(x=>x!==i):[...p,i])}>{checks.includes(i)?<Check size={16}/>:i+1}</button><span>{v}</span></li>)}</ol><p className="sample-note">加熱状態・アレルギー・食材の保存状態はご自身で確認してください。</p>{data&&<section className="recipe-cook-posts"><h3>このレシピで作った一皿</h3>{(community.data?.posts||[]).filter(p=>p.recipe===selected.id).map(post=><CookCard key={post.id} post={post} user={data.profile.id} onChanged={community.load} onError={communityError} onOpenRecipe={()=>{}}/>)}{!(community.data?.posts||[]).some(p=>p.recipe===selected.id)&&<p className="muted">最初の写真と感想を、作者に届けてみませんか。</p>}</section>}</div></div><aside className="detail-side"><p className="eyebrow">MAKE IT YOUR FAVORITE</p><h3>気になる一皿を、<br/>あなたの定番に。</h3><button className="primary" disabled={busy||saved(selected)} onClick={()=>saveRecipe(selected)}><Bookmark size={16}/>{saved(selected)?'棚に保存済み':'あなたの棚に保存'}</button><button className="secondary" disabled={busy} onClick={()=>cook(selected)}><ChefHat size={18}/>{cookedToday(selected)?'作った写真・感想を追加':'作った！を届ける'}</button><p>保存と調理報告で、原本の作者とのつながりを残します。</p><button className="ai-button detail-arrange" onClick={()=>{setArrangeRecipe(selected);setSelected(null);}}><Sparkles size={17}/>AIで自分用にアレンジ</button><small className="muted">人数・手持ちの食材・好みに合わせて、原本へのリンク付きで棚に保存できます。</small><div className="divider"/><h4>原本を共有する</h4><button className="secondary" onClick={()=>copyLink(selected)}><Copy size={15}/>リンクをコピー</button>{shareFallback&&<label>共有リンク<input readOnly value={shareFallback} onFocus={e=>e.target.select()}/></label>}<p>どのSNSで紹介しても、この原本へのリンクから棚に追加できます。</p><h4>作者の外部投稿</h4>{(data?.externalLinks||[]).filter(s=>s.recipe===selected.id).map(s=><a key={s.url} className="text-link" href={s.url} target="_blank" rel="noopener noreferrer">{new URL(s.url).hostname} <ExternalLink size={12}/></a>)}<span className="badge">{selected.chainStatus==='confirmed'?'Devnet記録済み':'チェーン未記録'}</span>{selected.signature&&<a className="text-link" href={explorer(selected.signature)} target="_blank" rel="noopener noreferrer">記録を照合 <ExternalLink size={12}/></a>}{selected.owner===data?.profile.id&&<button className="text-link" onClick={()=>edit(selected)}>このレシピを編集</button>}<button className="text-link report-link" onClick={()=>setReport(!report)}>盗用などの問題を報告</button>{report&&<div><textarea aria-label="報告理由" rows={4} value={reportReason} onChange={e=>setReportReason(e.target.value)} placeholder="元の投稿URLや理由を書いてください"/><button className="secondary" disabled={busy} onClick={()=>act(async()=>{await api({op:'report',recipe:selected.id,reason:reportReason});setReport(false);setReportReason('');flash('報告を記録しました。確認前に権利者を自動判定することはありません。');})}>報告を記録</button></div>}</aside></div></Modal>}
{editor&&<Modal busy={busy} title={editor.id?'レシピを改訂する':'あなたのひらめきを、レシピに。'} wide onClose={closeEditor}><div className="editor-grid"><fieldset className="editor-fields" disabled={busy} onChangeCapture={()=>{setAiSuggestion(null);setUndoDraft(null);setConsent(false);setSimilar([]);setAiError('');setAiCleanupAvailable(false);}}><div className="editor-guide"><b>1. 工夫をメモ → 2. AIで整理 → 3. 内容を確認して公開</b><p role="status">{draftSaved?'この端末に下書きを保存済み':'下書きは入力するとこの端末に保存されます'}</p></div><div className={'cloud-draft-status '+(cloud.conflict?'conflict':'')} role="status"><b>{cloud.status}</b>{cloud.conflict?<><p>内容が異なる下書きがあります。どちらを残すか選んでください。</p><p>クラウド：{cloud.conflict.draft?.payload.title||'削除済み・タイトル未入力'}</p>{cloud.conflict.draft&&<details><summary>クラウドの下書きを確認</summary><p className="pre-line">{cloud.conflict.draft.payload.description||'料理メモは未入力'}</p><p>{cloud.conflict.draft.payload.servings}人分 · {cloud.conflict.draft.payload.minutes}分 · {cloud.conflict.draft.payload.category}</p>{cloud.conflict.draft.payload.image!=='none'&&<Food image={cloud.conflict.draft.payload.image}/>}<p className="pre-line">{cloud.conflict.draft.payload.ingredients}</p><p className="pre-line">{cloud.conflict.draft.payload.steps}</p></details>}<div><button type="button" className="secondary" onClick={()=>cloud.resolve(true)}>クラウドの内容を使う</button><button type="button" className="secondary" onClick={()=>cloud.resolve(false)}>この端末の内容を使う</button></div></>:<button type="button" className="text-link" onClick={()=>cloud.retry()}>同期状態を再確認</button>}</div><label>レシピのタイトル <small>必須</small><input value={editor.title} maxLength={100} placeholder="例：レモン香る、春のパスタ" onChange={e=>setEditor({...editor,title:e.target.value})}/></label><label>こだわりポイント・料理メモ<textarea rows={4} value={editor.description} maxLength={600} placeholder="例：鶏むね肉でさっぱり。レモンを効かせて、辛さ控えめ。" onChange={e=>setEditor({...editor,description:e.target.value})}/></label><button className="ai-button" disabled={busy} onClick={()=>aiDraft('publish','compose')}><Sparkles size={15}/>こだわりからレシピ案を作る</button><small className="muted">短いメモだけでもOK。Gemini Flashが具材・分量・調理法を提案します。</small>{aiTask!=='refine'&&aiStatus&&<p className="ai-status" role="status" aria-live="polite">{aiStatus}</p>}{aiTask!=='refine'&&aiError&&<p className="form-error" role="alert">{aiError}</p>}<div className="field-row"><label>カテゴリー<select value={editor.category} onChange={e=>setEditor({...editor,category:e.target.value})}>{categories.slice(1).map(c=><option key={c}>{c}</option>)}</select></label><label>調理時間（分）<input type="number" min={1} max={1440} value={editor.minutes} onChange={e=>setEditor({...editor,minutes:Number(e.target.value)})}/></label><label>何人分<input type="number" min={1} max={100} value={editor.servings} onChange={e=>setEditor({...editor,servings:Number(e.target.value)})}/></label></div><label>材料・分量 <small>必須 · 1行につき1つ</small><textarea rows={6} value={editor.ingredients} maxLength={6000} placeholder={'鶏もも肉 300g\nトマト 2個'} onChange={e=>setEditor({...editor,ingredients:e.target.value})}/></label><label>つくり方 <small>必須 · 1行につき1工程</small><textarea rows={8} value={editor.steps} maxLength={10000} placeholder={'食材を切る。\nフライパンで加熱する。'} onChange={e=>setEditor({...editor,steps:e.target.value})}/></label><button type="button" className="ai-button full" disabled={busy||(!editor.ingredients.trim()&&!editor.steps.trim())} onClick={()=>aiDraft('publish','refine')}><Sparkles size={15}/>材料・分量・作り方をAIで仕上げる</button><small className="muted">入力済みの食材・分量を保ち、材料表記と工程を読みやすく整理します。</small>{aiTask==='refine'&&aiStatus&&<p className="ai-status" role="status" aria-live="polite">{aiStatus}</p>}{aiTask==='refine'&&aiError&&<p className="form-error" role="alert">{aiError}</p>}{aiError&&aiCleanupAvailable&&<div className="offline-cleanup"><p>AIが使えない間は、入力の空行・番号・余分な空白だけを整理できます。</p><button type="button" className="secondary full" disabled={busy||(!editor.ingredients.trim()&&!editor.steps.trim())} onClick={()=>{setAiSuggestion(cleanupRecipeInput(editor));setAiTask('refine');setAiStatus('入力だけを使った表記整理です。内容を確認して反映してください。');}}>AIなしで入力の表記を整理</button></div>}{undoDraft&&!aiSuggestion&&<button type="button" className="text-link" onClick={undoAiSuggestion}>反映前の内容に戻す</button>}{aiSuggestion&&<RecipeSuggestionReview suggestion={aiSuggestion} onApply={applyAiSuggestion} onDiscard={()=>{setAiSuggestion(null);setAiStatus('案を閉じました。入力内容は変わりません。');}}/>}</fieldset><aside className="editor-aside"><Food image={editor.image}/><label className="upload-control"><Upload size={16}/>自分の料理写真を選ぶ<input type="file" accept="image/png,image/jpeg,image/webp" disabled={busy} onChange={e=>{if(e.target.files?.[0])upload(e.target.files[0]);}}/></label><small className="muted">JPEG / PNG / WebP · 2MB以下 · 写真なしでも公開できます</small><div className="divider"/><h3>内容を確認して、公開。</h3>{editorIssue&&<p className="publish-checklist" role="status">{editorIssue}</p>}{aiSuggestion&&<p className="publish-checklist">AI案を反映するか閉じてから公開してください。</p>}<p>取り込みや調理に使われるレシピです。外部サイトから取り込んだ本文・写真をそのまま収益対象にすることはできません。</p><label className="checkbox-label"><input type="checkbox" checked={consent} onChange={e=>setConsent(e.target.checked)}/>自分が権利を持つか必要な許可を得た内容です。アプリ内での表示・棚への取り込み・調理利用を許可して公開します。</label>{similar.length>0&&<div className="similar-warning"><b>似たレシピが見つかりました</b>{similar.map(r=><p key={r.id}>{r.title}</p>)}<button className="secondary" disabled={busy||!consent||!!aiSuggestion||!!editorIssue} onClick={()=>publish(true)}>独自性・権利を確認して公開</button></div>}<button className="primary" disabled={busy||!consent||!!aiSuggestion||!!editorIssue} onClick={()=>publish()}><PenLine size={16}/>{editor.id?'改訂版を公開':'レシピを公開する'}</button><small className="muted">公開後も編集・非公開化できます。チェーン記録は別途、ウォレットで確認して実行します。</small><button type="button" className="secondary full" disabled={busy} onClick={closeEditor}>下書きを保存して閉じる</button><p className="field-help">下書きは同じアカウントの端末間で同期します。通信できない間も、この端末の保存内容を残します。</p><button type="button" className="text-link" disabled={busy} onClick={discardDraft}>この下書きを破棄する</button></aside></div></Modal>}
{importOpen&&<Modal busy={busy} title="外部のレシピを、あなたの棚へ。" onClose={()=>{if(!mediaBusy)setImportOpen(false);}}><div className="modal-body"><fieldset className="plain-fieldset" disabled={busy||mediaBusy}><div className="inline-note"><Link2 size={20}/><p>作者が確認済みの投稿や、つくりての直リンクなら原本につなぎます。それ以外は非公開の自分用メモになり、収益対象にはなりません。</p></div><label>投稿URL・つくりての原本リンク<input type="url" inputMode="url" value={importForm.url} placeholder="https://…" onChange={e=>setImportForm({...importForm,url:e.target.value})}/></label>{importForm.url&&!isHttpsUrl(importForm.url)&&<p className="form-error" role="alert">https:// で始まる投稿URLを入力してください。</p>}<label>メモのタイトル <small>未連携の場合に使用</small><input value={importForm.title} maxLength={100} onChange={e=>setImportForm({...importForm,title:e.target.value})}/></label><label>出典の作者名・自分用メモ<textarea rows={4} value={importForm.notes} maxLength={6000} onChange={e=>setImportForm({...importForm,notes:e.target.value})} placeholder="元の作者名や、自分が確認できる材料・手順のメモ。URLだけで動画の内容を自動取得する機能ではありません。"/></label><label>スクリーンショット（6枚まで・各2MB以下）<input key={mediaKey} type="file" accept="image/jpeg,image/png,image/webp" multiple onChange={async e=>{const target=e.currentTarget;const files=Array.from(target.files||[]);setMediaBusy(true);try{if(files.length>6||files.some(f=>f.size>2097152))throw Error('画像は6枚まで、各2MB以下で選択してください。');const media=await Promise.all(files.map(f=>new Promise<{base64:string;mimeType:string}>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({base64:String(reader.result).split(',')[1],mimeType:f.type});reader.onerror=()=>reject(Error('画像を読み込めませんでした。'));reader.readAsDataURL(f);})));setImportMedia(media);setMediaNames(files.map(f=>f.name));}catch(error){setImportMedia([]);setMediaNames([]);target.value='';flash((error as Error).message,'error');}finally{setMediaBusy(false);}}}/><small>添付した画像は抽出時にGeminiへ送ります。AI処理後、画像そのものは保存しません。</small></label>{mediaNames.length>0&&<div className="media-summary"><span>{mediaNames.length}枚を添付済み</span><button type="button" className="text-link" onClick={()=>{setImportMedia([]);setMediaNames([]);setMediaKey(k=>k+1);}}>添付を外す</button></div>}<button className="ai-button full" disabled={busy||(!importForm.notes.trim()&&!importMedia.length&&!isHttpsUrl(importForm.url))} onClick={()=>aiDraft('import')}><Sparkles size={16}/>メモ・画像から材料と手順を抽出</button>{aiStatus&&<p className="ai-status" role="status" aria-live="polite">{aiStatus}</p>}{aiError&&<p className="form-error" role="alert">{aiError}</p>}<label>材料<textarea rows={3} value={importForm.ingredients} onChange={e=>setImportForm({...importForm,ingredients:e.target.value})}/></label><label>手順<textarea rows={4} value={importForm.steps} onChange={e=>setImportForm({...importForm,steps:e.target.value})}/></label><button className="primary full" disabled={busy||!isHttpsUrl(importForm.url)} onClick={()=>act(async()=>{const j=await api({op:'import',...importForm,url:importForm.url.trim()});await load();setImportOpen(false);setImportForm({url:'',title:'',notes:'',ingredients:'',steps:''});setImportMedia([]);setMediaNames([]);go('shelf');flash(j.linked?'作者の原本につないで棚に保存しました。':'出典付きの自分用メモとして保存しました。');})}><Library size={16}/>棚に取り込む</button>{!importForm.url&&<p className="field-help">出典を残すため、保存には元の投稿URLが必要です。</p>}</fieldset></div></Modal>}
{sourceOpen&&<Modal busy={busy} title="他のSNSからも、原本につなぐ。" onClose={()=>setSourceOpen(false)}><div className="modal-body"><p>あなたが管理する投稿を登録し、発行した確認コードを掲載します。YouTube・TikTokは公開メタデータで確認。他の媒体は未確認のまま自動連携を止めます。</p><label>紐づける原本<select value={sourceForm.recipe} onChange={e=>setSourceForm({...sourceForm,recipe:e.target.value})}><option value="">レシピを選択</option>{own.filter(r=>r.status==='published').map(r=><option key={r.id} value={r.id}>{r.title}</option>)}</select></label><label>自分が管理する投稿のURL<input value={sourceForm.url} placeholder="https://www.youtube.com/watch?v=…" onChange={e=>setSourceForm({...sourceForm,url:e.target.value})}/></label><button className="primary full" disabled={busy||!sourceForm.recipe||!sourceForm.url} onClick={()=>act(async()=>{const j=await api({op:'sourceAdd',...sourceForm});await load();setSourceOpen(false);go('creator');flash('確認コードを発行しました：'+j.code);})}>確認コードを発行</button><p className="muted">投稿の管理権限の確認と、レシピの著作権の認定は別です。SNSの取得制限により確認できない場合があります。</p></div></Modal>}
{privateItem&&<Modal busy={busy} title="自分用の外部レシピメモ" onClose={()=>setPrivateItem(null)}><div className="modal-body"><span className="badge">非公開 · チェーン未登録 · 分配対象外</span><h2>{privateItem.title}</h2>{!privateItem.url.startsWith('app:')&&<a className="text-link" href={privateItem.url} target="_blank" rel="noopener noreferrer">元の投稿を開く <ExternalLink size={13}/></a>}<p className="pre-line">{privateItem.notes}</p><h3>材料</h3><p className="pre-line">{privateItem.ingredients||'未入力'}</p><h3>つくり方</h3><ol className="steps-list">{privateItem.steps.split('\n').filter(Boolean).map((step:string,i:number)=><li key={i} className={checks.includes(i)?'checked':''}><button aria-pressed={checks.includes(i)} aria-label={'手順'+(i+1)+'をチェック'} onClick={()=>setChecks(p=>p.includes(i)?p.filter(x=>x!==i):[...p,i])}>{checks.includes(i)?<Check size={16}/>:i+1}</button><span>{step}</span></li>)}</ol>{!privateItem.steps&&<p>手順は未入力です。</p>}{!privateItem.url.startsWith('app:')&&<button className="secondary" onClick={()=>{setImportForm({url:privateItem.url,title:privateItem.title,notes:privateItem.notes,ingredients:privateItem.ingredients,steps:privateItem.steps});setPrivateItem(null);setImportMedia([]);setMediaNames([]);setAiStatus('');setImportOpen(true);}}>メモを編集</button>}</div></Modal>}
{testTransfer&&<Modal busy={busy} title="Devnetの送金を試す" onClose={()=>setTestTransfer(false)}><div className="modal-body"><div className="inline-note"><Info size={20}/><p>0.0001テストSOLの接続確認です。報酬の支払いではありません。接続したウォレットが送金元となり、Devnetの残高と手数料が必要です。</p></div><label>送付先ウォレット<input value={recipient} onChange={e=>setRecipient(e.target.value)} placeholder="Solanaの公開アドレス"/></label><p className="muted">自分のアドレスを指定して動作確認することもできます。</p><button className="primary full" disabled={busy} onClick={sendTest}>ウォレットで確認して送信</button></div></Modal>}
{publicationConflict&&editor&&<Modal title="原本の更新を確認してください" wide onClose={()=>setPublicationConflict(null)}><div className="modal-body"><p>別の端末で原本が更新されています。入力は残しています。内容を比べ、どちらを元に編集するか選んでください。</p><div className="publication-compare"><section><h3>あなたの入力</h3><b>{editor.title}</b><pre>{editor.ingredients+'\n\n'+editor.steps}</pre></section><section><h3>公開中の最新版 v{publicationConflict.version}</h3><b>{publicationConflict.title}</b><pre>{publicationConflict.ingredients+'\n\n'+publicationConflict.steps}</pre></section></div><div className="publication-actions"><button className="primary" onClick={()=>{setEditor((p:any)=>({...p,version:publicationConflict.version}));setPublicationConflict(null);setConsent(false);}}>最新版を確認し、自分の入力で編集を続ける</button><button className="secondary" onClick={()=>{setEditor({...publicationConflict});setPublicationConflict(null);setConsent(false);}}>公開中の最新版を使う</button></div><p className="field-help">選択だけでは公開しません。編集画面で内容と公開許諾をもう一度確認してください。</p></div></Modal>}
{shareFallback&&!selected&&<Modal title="共有リンク" onClose={()=>setShareFallback('')}><div className="modal-body"><p>リンクを長押し、または選択してコピーできます。</p><label>原本へのリンク<input readOnly value={shareFallback} onFocus={e=>e.target.select()}/></label></div></Modal>}
{help&&<Modal busy={busy} title="つくりての仕組み・利用ルール" onClose={()=>setHelp(false)}><div className="modal-body help-copy"><p className="eyebrow">GOOD FOOD, SHARED VALUE.</p><h2>おいしいが、めぐる場所。</h2><h3>発信する人へ</h3><p>自分が権利を持つか、必要な許可を得た説明・写真を公開してください。料理のアイデアや料理名を独占するサービスではありません。類似レシピの検出は確認の補助で、世界で唯一のレシピと認定する機能ではありません。</p><h3>保存して、作る人へ</h3><p>原本の作者への参照を保ったまま棚に追加します。外部からの未連携取り込みは自分用で、一般公開・チェーン登録・分配の対象にしません。元の作者・出典はメモに残してください。外部コンテンツの取り込み・利用は各媒体の条件と権利を確認してください。</p><h3>Solanaに記録するもの</h3><p>原本ID・レシピ本文のハッシュ・登録ウォレット、Devnetの送金履歴です。本文や個人の調理履歴をチェーンに送りません。登録者が本当の作者であること、著作権、実際に調理した事実をチェーンが保証するわけではありません。記録は公開され、後から本文を非公開にしてもチェーン履歴は残ります。</p><h3>収益の計算</h3><p>現在はDevnetの試作です。実売上・広告配信・サブスク課金・本番報酬は未接続。仮の月額分配枠0.001テストSOLを、有効ポイントの割合で試算します。保存1pt、同じレシピの調理報告は1日1回3pt、全体で1日10報告まで。自己利用・サンプルは除外します。複数アカウント不正を完全に防ぐ機能ではなく、実際の支払い前には審査・規約・税務等の整備が必要です。</p><h3>報告と非公開化</h3><p>問題がある投稿は詳細画面から報告できます。報告は保存されますが、自動的に削除・権利認定されません。作者は自分の投稿を非公開にできます。サンプル作者・写真は体験用で、実在の作者・売上を表しません。</p><h3>データ</h3><p>アカウントはこのアプリ専用です。既存のれしぴ棚にはアクセスしません。プロフィールからJSONを書き出せます。レシピ抽出はSupabase Edge Functions経由でGemini Flashを利用します。AIに送信する内容を確認してください。無料枠保護のため回数に制限があります。</p></div></Modal>}
{data&&notificationOpen&&<Notifications state={community.data} user={data.profile.id} onChanged={community.load} onError={communityError} onClose={()=>setNotificationOpen(false)} onOpen={openNotice}/>}
{data&&cookRecipe&&<CookComposer recipe={cookRecipe} already={cookedToday(cookRecipe)} user={data.profile.id} onChanged={community.load} onError={communityError} onSuccess={async()=>{await load();flash('作った一皿を記録しました。');}} onClose={()=>setCookRecipe(null)}/>}
{data&&arrangeRecipe&&<ArrangeDialog recipe={arrangeRecipe} user={data.profile.id} onChanged={community.load} onError={communityError} onClose={()=>setArrangeRecipe(null)} onSaved={()=>{go('shelf');flash('自分用アレンジを棚に保存しました。');}}/>}
{data&&thread&&<Modal title="作った投稿とコメント" onClose={()=>setThread(null)}><div className="notification-thread"><CookCard post={thread} expanded user={data.profile.id} onChanged={community.load} onError={communityError} onOpenRecipe={openRecipeId}/></div></Modal>}
{busy&&createPortal(<div data-modal-exempt className="busy-indicator" role="status"><LoaderCircle className="spin" size={16}/>{aiStatus||'処理しています…'}</div>,document.body)}{notice&&createPortal(<div data-modal-exempt className={'toast '+(noticeTone==='error'?'toast-error':'')} role={noticeTone==='error'?'alert':'status'}>{noticeTone==='error'?<AlertCircle size={17}/>:<Check size={17}/>}{notice}<button aria-label="通知を閉じる" onClick={()=>setNotice('')}><X size={16}/></button></div>,document.body)}
</div>;
}
function PageTitle({eyebrow,title,text}:{eyebrow:string;title:string;text:string}){return <div className="page-title"><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p>{text}</p></div>;}
